class Product extends DataClass implements Insertable<Product> {
  final String id;
  final String name;

  /// Kandungan / nama generik, mis. "Paracetamol 500 mg". Ikut dicari.
  final String genericName;
  final String category;
  final DrugClass drugClass;

  /// Nama file foto di folder foto produk (bukan path lengkap).
  final String? photoFile;

  /// Batas stok menipis, dalam satuan terkecil. 0 = tidak diperingatkan.
  final int minStock;

  /// Produk yang diarsipkan tidak tampil di kasir, tetapi riwayatnya tetap ada.
  final bool isActive;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Product({
    required this.id,
    required this.name,
    required this.genericName,
    required this.category,
    required this.drugClass,
    this.photoFile,
    required this.minStock,
    required this.isActive,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['generic_name'] = Variable<String>(genericName);
    map['category'] = Variable<String>(category);
    {
      map['drug_class'] = Variable<String>(
        $ProductsTable.$converterdrugClass.toSql(drugClass),
      );
    }
    if (!nullToAbsent || photoFile != null) {
      map['photo_file'] = Variable<String>(photoFile);
    }
    map['min_stock'] = Variable<int>(minStock);
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ProductsCompanion toCompanion(bool nullToAbsent) {
    return ProductsCompanion(
      id: Value(id),
      name: Value(name),
      genericName: Value(genericName),
      category: Value(category),
      drugClass: Value(drugClass),
      photoFile: photoFile == null && nullToAbsent
          ? const Value.absent()
          : Value(photoFile),
      minStock: Value(minStock),
      isActive: Value(isActive),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Product.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Product(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      genericName: serializer.fromJson<String>(json['genericName']),
      category: serializer.fromJson<String>(json['category']),
      drugClass: $ProductsTable.$converterdrugClass.fromJson(
        serializer.fromJson<String>(json['drugClass']),
      ),
      photoFile: serializer.fromJson<String?>(json['photoFile']),
      minStock: serializer.fromJson<int>(json['minStock']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'name': serializer.toJson<String>(name),
      'genericName': serializer.toJson<String>(genericName),
      'category': serializer.toJson<String>(category),
      'drugClass': serializer.toJson<String>(
        $ProductsTable.$converterdrugClass.toJson(drugClass),
      ),
      'photoFile': serializer.toJson<String?>(photoFile),
      'minStock': serializer.toJson<int>(minStock),
      'isActive': serializer.toJson<bool>(isActive),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

